Röviden: egy ilyen “valós idejű, teljes webhelyet átfogó” akciófigyelő PWA megvalósítható, de a kért domainek teljes körű, folyamatos feltérképezése és árazási akciók kinyerése jogi (robots.txt, ÁSZF), technikai (rate-limit, anti-bot, dinamikus SPA renderelés), valamint üzemeltetési kihívásokat vet fel, ezért célszerű hivatalos termékfeedet/API-t, vagy legfeljebb tisztességes, robots.txt-t tiszteletben tartó feltérképezést és gyorsítótárat alkalmazni.[1][4]

Lényeges koncepciók a valós telepíthetőséghez
- Valós idejű frissítés: queue + schedule (pl. Celery/APS, vagy asyncio feladatok) 1–5 perc frissítési ciklus, domainenként külön rate limitinggel, hibatűréssel és visszavonuló exponenciális késleltetéssel.[1][4]  
- Teljes webhely bejárás: induló URL-lista (főoldal + fontos kategóriák), BFS/DFS korlátozott mélységgel, canonical és noindex tiszteletben tartása, robots.txt ellenőrzés, illetve deduplikáció hash-sel.[1][4]  
- Akciók és kedvezmények felismerése: nyelvi-heurisztikák (pl. “-xx%”, “kedvezmény”, “akció”, “leárazás”), árpár-extrakció (eredeti vs. akciós ár), CSS/JSON-LD sémák (Product, Offer) parse-olása, és százalékszámítás fallback-kel, ha explicit kedvezmény nincs.[1][4]  
- Dinamikus oldalak: headless renderelő réteg (pl. Playwright/Chromium) csak a szükséges útvonalakon, külön pool-ban és timeout-tal a költségek megfogására.[1][4]  
- Adatminőség: normálás (HUF), kedvezmény = round((1 - akcios_ar/eredeti_ar)*100), minőség-ellenőrzés küszöbökkel (pl. 5–95%).[1][4]  
- PWA: manifest, service worker, offline cache, iOS telepíthetőség, standalone, status bar beállítások, splash ikonok; a megadott meta-k kulcsai rendben vannak, csak a service worker és az ikonok/manifest kell hozzá.[1]  
- Exa/OpenAI: használható kiegészítőként struktúrázatlan tartalmak szöveg-összefoglalására és kedvezmény-kontekstre, de ár/kupon végső számítást determinisztikusan, szabályok alapján kell végezni.[1][4]

Az alábbi kód deployolható alapot ad, valós scrapinggel (robots.txt-t tiszteletben tartva), async HTTP-vel, Playwright fallbackkel és PWA-frontenddel.

main.py (FastAPI + async crawler + Playwright fallback)
```python
# main.py
import asyncio, re, time, json, os, math, hashlib
from urllib.parse import urljoin, urlparse
from typing import List, Dict, Optional, Tuple
from fastapi import FastAPI, Response
from fastapi.staticfiles import StaticFiles
from fastapi.responses import JSONResponse, FileResponse
import httpx

# Opcionális: headless render Playwright-hoz
PLAYWRIGHT_ENABLED = os.getenv("PLAYWRIGHT_ENABLED", "1") == "1"

# Cél domainek
DOMAINEK = [
    "",
    "",
    "",
    "",
    "",
    "",
]

# Állapot
CACHE: Dict[str, Dict] = {}
AKCIOK: List[Dict] = []
LAST_FULL_CRAWL = 0
CRAWL_INTERVAL_SEC = 300  # 5 perc

# HTTP kliens
client = httpx.AsyncClient(timeout=20.0, headers={"User-Agent": "AkciofigyeloBot/1.0 (+contact: admin@example.com)"})

ROBOT_CACHE: Dict[str, str] = {}
VISITED: set = set()

# Heurisztikák
DISCOUNT_RE = re.compile(r"(-?\d{1,3})\s?%|(\d{3,7})\s*Ft", re.IGNORECASE)
PRICE_RE = re.compile(r"(\d{1,3}(?:[\s\.]\d{3})*|\d+)\s*Ft", re.IGNORECASE)

def norm_price(s: str) -> Optional[int]:
    m = PRICE_RE.search(s.replace("\xa0"," "))
    if not m: return None
    num = m.group(1).replace(" ", "").replace(".", "")
    try: return int(num)
    except: return None

def url_host(u: str) -> str:
    return urlparse(u).netloc.lower()

async def get_robots_txt(base: str) -> str:
    host = url_host(base)
    if host in ROBOT_CACHE: return ROBOT_CACHE[host]
    robots_url = f"{urlparse(base).scheme}://{host}/robots.txt"
    try:
        r = await client.get(robots_url)
        if r.status_code == 200:
            ROBOT_CACHE[host] = r.text
            return r.text
    except:
        pass
    ROBOT_CACHE[host] = ""
    return ""

def is_allowed_by_robots(base: str, path: str) -> bool:
    # Minimál disallow parser
    content = ROBOT_CACHE.get(url_host(base), "")
    lines = content.splitlines()
    dis = []
    ua_block = None
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"): continue
        if line.lower().startswith("user-agent:"):
            ua = line.split(":",1)[1].strip()
            ua_block = (ua == "*" or ua.lower() == "akciofigyelobot")
        elif ua_block and line.lower().startswith("disallow:"):
            p = line.split(":",1)[1].strip()
            dis.append(p)
    for d in dis:
        if d and path.startswith(d):
            return False
    return True

def hash_url(u: str) -> str:
    return hashlib.sha256(u.encode()).hexdigest()[:16]

def extract_links(base: str, html: str) -> List[str]:
    # Egyszerű link-kinyerés
    out = []
    for m in re.finditer(r'href=["\']([^"\']+)["\']', html, re.IGNORECASE):
        href = m.group(1)
        if href.startswith("javascript:") or href.startswith("mailto:"):
            continue
        absu = urljoin(base, href)
        if url_host(absu) == url_host(base):
            out.append(absu.split("#")[0])
    return list(dict.fromkeys(out))

def extract_image(html: str) -> Optional[str]:
    m = re.search(r'<img[^>]+src=["\']([^"\']+)["\']', html, re.IGNORECASE)
    return m.group(1) if m else None

def calc_discount(text: str) -> Optional[int]:
    # Közvetlen %-os minták
    for m in re.finditer(r'(-?\d{1,3})\s?%', text):
        try:
            val = int(m.group(1))
            if -95 <= val <= 95:
                return abs(val)
            if -100 <= val <= 100:
                return abs(val)
        except:
            pass
    return None

def extract_title(html: str) -> str:
    mt = re.search(r'<title>(.*?)</title>', html, re.IGNORECASE|re.DOTALL)
    if mt:
        return re.sub(r'\s+', ' ', mt.group(1)).strip()
    mh = re.search(r'<h1[^>]*>(.*?)</h1>', html, re.IGNORECASE|re.DOTALL)
    if mh:
        return re.sub(r'\s+', ' ', re.sub('<[^<]+?>','', mh.group(1))).strip()
    return "Akció"

def compute_discount_from_prices(text: str) -> Optional[int]:
    # Eredeti és akciós ár becslése, ha több ár van a szövegben
    prices = [p for p in (norm_price(text) for _ in range(1)) if p]  # placeholder
    # Egyszerű fallback: nem használjuk, mert szövegben ritkán stabil
    return None

async def fetch_url(u: str, render: bool=False) -> Optional[str]:
    try:
        r = await client.get(u, follow_redirects=True)
        if r.status_code == 200 and "text/html" in r.headers.get("content-type",""):
            return r.text
    except:
        return None
    # Playwright fallback opcionálisan
    if render and PLAYWRIGHT_ENABLED:
        try:
            from playwright.async_api import async_playwright
            async with async_playwright() as p:
                browser = await p.chromium.launch(headless=True)
                page = await browser.new_page(user_agent="AkciofigyeloBot/1.0")
                await page.goto(u, wait_until="load", timeout=20000)
                html = await page.content()
                await browser.close()
                return html
        except:
            return None
    return None

def looks_like_deal(html: str) -> bool:
    hay = html.lower()
    return any(k in hay for k in ["akció", "akci\u00f3", "kedvezm", "%", "leárazás", "sale", "ár"])


async def crawl_domain(start: str, max_pages: int=60, render_paths: Tuple[str,...]=("/product","/termek","/sku","/p/")) -> List[Dict]:
    host = url_host(start)
    robots = await get_robots_txt(start)
    queue = [start]
    seen = set()
    results = []
    pages = 0

    while queue and pages < max_pages:
        u = queue.pop(0)
        if u in seen: continue
        seen.add(u)
        path = urlparse(u).path or "/"
        if not is_allowed_by_robots(start, path):
            continue

        render = any(seg in path for seg in render_paths)
        html = await fetch_url(u, render=render)
        if not html: continue
        pages += 1

        if looks_like_deal(html):
            # Próbáljunk %-ot kinyerni
            perc = calc_discount(html)
            if perc is None:
                perc = compute_discount_from_prices(html) or None
            if perc is not None:
                title = extract_title(html)
                img = extract_image(html)
                results.append({
                    "title": title,
                    "url": u,
                    "kedvezmeny": int(perc),
                    "webshop": host,
                    "kep": urljoin(u, img) if img else None
                })

        # Linkbővítés (korlátozott)
        for v in extract_links(u, html):
            if v not in seen and url_host(v) == host and len(seen) + len(queue) < max_pages*3:
                queue.append(v)
    return results

async def full_refresh():
    global AKCIOK, LAST_FULL_CRAWL, VISITED
    all_res = []
