from urllib.parse import urljoin, urlparse
from typing import List, Dict, Optional, Tuple
from fastapi import FastAPI, Response
from fastapi.responses import JSONResponse
from fastapi.staticfiles import StaticFiles
import httpx

# Opcionális: headless render Playwright-hoz (SPA oldalakhoz)
PLAYWRIGHT_ENABLED = os.getenv("PLAYWRIGHT_ENABLED", "1") == "1"

DOMAINEK = [
    "",
    "",
    "",
    "",
    "",
    "",
]

AKCIOK: List[Dict] = []
LAST_FULL_CRAWL = 0
CRAWL_INTERVAL_SEC = int(os.getenv("CRAWL_INTERVAL_SEC", "300"))  # 5 perc
MAX_PAGES = int(os.getenv("MAX_PAGES", "80"))

client = httpx.AsyncClient(
    timeout=20.0,
    headers={"User-Agent": "Akciofigyelo/1.0 (+contact: admin@example.com)"},
    follow_redirects=True,
)

ROBOT_CACHE: Dict[str, str] = {}

def host_of(u: str) -> str:
    return urlparse(u).netloc.lower()

async def get_robots(base: str) -> str:
    h = host_of(base)
    if h in ROBOT_CACHE:
        return ROBOT_CACHE[h]
    robots_url = f"{urlparse(base).scheme}://{h}/robots.txt"
    try:
        r = await client.get(robots_url)
        ROBOT_CACHE[h] = r.text if r.status_code == 200 else ""
    except:
        ROBOT_CACHE[h] = ""
    return ROBOT_CACHE[h]

def allowed(base: str, path: str) -> bool:
    # nagyon egyszerű Disallow parser
    content = ROBOT_CACHE.get(host_of(base), "")
    lines = [ln.strip() for ln in content.splitlines()]
    relevant = False
    rules = []
    for ln in lines:
        if not ln or ln.startswith("#"):
            continue
        if ln.lower().startswith("user-agent:"):
            ua = ln.split(":",1)[1].strip().lower()
            relevant = ua in ("*", "akciofigyelo")
        elif relevant and ln.lower().startswith("disallow:"):
            p = ln.split(":",1)[1].strip() or "/"
            rules.append(p)
    for d in rules:
        if d == "/":
            return False
        if d and path.startswith(d):
            return False
    return True

LINK_RE = re.compile(r'href=["\']([^"\']+)["\']', re.IGNORECASE)
IMG_RE = re.compile(r'<img[^>]+src=["\']([^"\']+)["\']', re.IGNORECASE)
TITLE_RE = re.compile(r'<title>(.*?)</title>', re.IGNORECASE|re.DOTALL)
PERCENT_RE = re.compile(r'(?<!\d)(-?\d{1,3})\s?%', re.IGNORECASE)
PRICE_RE = re.compile(r'(\d{1,3}(?:[ .]\d{3})*|\d+)\s*Ft', re.IGNORECASE)

def abs_url(base: str, href: str) -> Optional[str]:
    if href.startswith("javascript:") or href.startswith("mailto:"):
        return None
    u = urljoin(base, href)
    return u.split("#")[0]

def extract_links(base: str, html: str) -> List[str]:
    out = []
    for m in LINK_RE.finditer(html):
        u = abs_url(base, m.group(1))
        if not u:
            continue
        if host_of(u) == host_of(base):
            out.append(u)
    # dedup, stabil sorrend
    seen = set()
    uniq = []
    for u in out:
        if u not in seen:
            seen.add(u)
            uniq.append(u)
    return uniq

def extract_title(html: str) -> str:
    m = TITLE_RE.search(html)
    if not m:
        return "Akció"
    t = m.group(1)
    t = re.sub(r'\s+', ' ', t)
    return t.strip()

def extract_image(html: str, base_url: str) -> Optional[str]:
    m = IMG_RE.search(html)
    if not m:
        return None
    return urljoin(base_url, m.group(1))

def parse_price(text: str) -> List[int]:
    out = []
    for m in PRICE_RE.finditer(text.replace("\xa0", " ")):
        num = m.group(1).replace(" ", "").replace(".", "")
        try:
            out.append(int(num))
        except:
            pass
    return out

def compute_discount_from_prices(all_text: str) -> Optional[int]:
    prices = parse_price(all_text)
    if len(prices) < 2:
        return None
    hi = max(prices)
    lo = min(prices)
    if hi <= 0 or lo <= 0 or lo > hi:
        return None
    disc = round((1 - (lo/hi)) * 100)
    if 1 <= disc <= 95:
        return disc
    return None

def find_percent(html: str) -> Optional[int]:
    best = None
    for m in PERCENT_RE.finditer(html):
        try:
            val = abs(int(m.group(1)))
            if 1 <= val <= 95:
                best = max(best or 0, val)
        except:
            continue
    return best

def looks_like_deal(html: str) -> bool:
    low = html.lower()
    keys = ("akció", "kedvezm", "leárazás", "sale", "%", "kupon", "ár", "akcios")
    return any(k in low for k in keys)

async def fetch_html(u: str, render: bool=False) -> Optional[str]:
    try:
        r = await client.get(u)
        if r.status_code == 200 and "text/html" in r.headers.get("content-type",""):
            return r.text
    except:
        pass
    if render and PLAYWRIGHT_ENABLED:
        try:
            from playwright.async_api import async_playwright
            async with async_playwright() as p:
                browser = await p.chromium.launch(headless=True)
                page = await browser.new_page(user_agent="Akciofigyelo/1.0")
                await page.goto(u, wait_until="load", timeout=25000)
                html = await page.content()
                await browser.close()
                return html
        except:
            return None
    return None

async def crawl_domain(start: str, max_pages: int) -> List[Dict]:
    await get_robots(start)
    host = host_of(start)
    queue = [start]
    seen = set()
    results: List[Dict] = []
    count = 0
    while queue and count < max_pages:
        u = queue.pop(0)
        if u in seen:
            continue
        seen.add(u)
        path = urlparse(u).path or "/"
        if not allowed(start, path):
            continue
        # Heurisztika: termék/kategória útvonalaknál render fallback
        render = any(seg in path for seg in ("/termek", "/product", "/p/", "/sku", "/category", "/kategori"))
        html = await fetch_html(u, render=render)
        if not html:
            continue
        count += 1

        if looks_like_deal(html):
            pct = find_percent(html)
            if pct is None:
                pct = compute_discount_from_prices(html)
            if pct:
                results.append({
                    "title": extract_title(html) or host,
                    "url": u,
                    "kedvezmeny": int(pct),
                    "webshop": host,
                    "kep": extract_image(html, u)
                })

        for v in extract_links(u, html):
            if v not in seen and host_of(v) == host and len(seen) + len(queue) < max_pages*3:
                queue.append(v)
    return results

def key_url(u: str) -> str:
    return hashlib.sha256(u.encode()).hexdigest()[:16]

async def full_refresh():
    global AKCIOK, LAST_FULL_CRAWL
    tasks = [crawl_domain(d, MAX_PAGES) for d in DOMAINEK]
    groups = await asyncio.gather(*tasks, return_exceptions=True)
    merged: List[Dict] = []
    for g in groups:
        if isinstance(g, list):
            merged.extend(g)
    # deduplikálás URL alapján, max kedvezmény megtartása
    best: Dict[str, Dict] = {}
    for it in merged:
        k = key_url(it["url"])
        cur = best.get(k)
        if (cur is None) or (it["kedvezmeny"] > cur["kedvezmeny"]):
            best[k] = it
    AKCIOK = sorted(best.values(), key=lambda x: x["kedvezmeny"], reverse=True)
    LAST_FULL_CRAWL = int(time.time())

