  <div id="chips" class="flex gap-2 flex-wrap">
    <button data-q="tej" class="chip px-3 py-1 rounded-full text-sm">tej</button>
    <button data-q="uht" class="chip px-3 py-1 rounded-full text-sm">uht</button>
    <button data-q="3.5%" class="chip px-3 py-1 rounded-full text-sm">3.5%</button>
    <button data-q="2.8%" class="chip px-3 py-1 rounded-full text-sm">2.8%</button>
  </div>

  <section>
    <div id="actions-list" class="space-y-4 max-h-[70vh] overflow-y-auto pr-2"></div>
  </section>

  <section class="flex justify-between items-center">
    <div class="text-sm text-gray-600 select-none">Utolsó frissítés: <span id="last-update">-</span></div>
    <div class="text-xs text-gray-500 select-none">Valós idejű figyelés: jysk.hu, dm.hu, douglas.hu, euronic.hu, praktiker.hu, moebelix.hu</div>
  </section>
</main>

<footer class="mt-8 text-center text-xs text-gray-500 select-none">
  &copy; 2025 Akciófigyelő • PWA iOS támogatással
</footer>

<script>
  let allAkciok = [];

  async function fetchAkciok() {
    const res = await fetch('/api/akciok', { cache: 'no-store' });
    if (!res.ok) throw new Error('Hiba a szerverről');
    const data = await res.json();
    return data.akciok || [];
  }

  function renderAkciok(akciok) {
    const container = document.getElementById('actions-list');
    container.innerHTML = '';
    if (akciok.length === 0) {
      container.innerHTML = '<p class="text-center text-gray-500">Nincs elérhető akció.</p>';
      return;
    }
    akciok.forEach(({title, url, kedvezmeny, webshop, kep}) => {
      const a = document.createElement('a');
      a.href = url;
      a.target = '_blank';
      a.rel = 'noopener noreferrer';
      a.className = 'block p-4 rounded-xl bg-white/30 backdrop-blur-md border border-white/40 shadow-md hover:shadow-lg transition-shadow duration-300';
      a.innerHTML = `
        <div class="flex items-center gap-4">
          <img src="${kep || ''}" alt="Akció: ${title}" class="w-20 h-20 rounded-lg object-cover flex-shrink-0" loading="lazy" />
          <div class="flex-1 min-w-0">
            <h3 class="font-semibold text-gray-900 truncate">${title}</h3>
            <p class="text-sm text-gray-700 truncate">${webshop}</p>
            <p class="mt-1 text-blue-700 font-bold text-lg">${kedvezmeny}% kedvezmény</p>
          </div>
          <svg xmlns="" class="w-5 h-5 text-blue-700 flex-shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2" aria-hidden="true"><path stroke-linecap="round" stroke-linejoin="round" d="M9 5l7 7-7 7"/></svg>
        </div>
      `;
      container.appendChild(a);
    });
  }

  function applyFilter() {
    const q = document.getElementById('filter').value.trim().toLowerCase();
    if (!q) return renderAkciok(allAkciok);
    const filtered = allAkciok.filter(x =>
      (x.title || '').toLowerCase().includes(q) ||
      (x.webshop || '').toLowerCase().includes(q)
    );
    renderAkciok(filtered);
  }

  async function updateAkciok() {
    const btn = document.getElementById('refresh-btn');
    btn.disabled = true;
    btn.textContent = 'Frissítés...';
    try {
      allAkciok = await fetchAkciok();
      renderAkciok(allAkciok);
      document.getElementById('last-update').textContent = new Date().toLocaleTimeString('hu-HU');
    } catch (e) {
      console.error(e);
    } finally {
      btn.disabled = false;
      btn.textContent = 'Frissítés';
    }
  }

  document.getElementById('refresh-btn').addEventListener('click', updateAkciok);
  document.getElementById('filter').addEventListener('input', applyFilter);
  document.getElementById('chips').addEventListener('click', (e) => {
    const q = e.target?.dataset?.q;
    if (q) {
      document.getElementById('filter').value = q;
      applyFilter();
    }
  });

  // SW reg, PWA iOS
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('/sw.js').catch(console.error);
    });
  }

  // Induláskor automatikus frissítés
  updateAkciok();
</script>
</body>
</html>
